/* For each of the 4 valid save slots, clear per-slot state and set rumble flags to 2. */ void resetRumbleForValidSlots(void) {
    s32 slot;

    slot = 0;
    do {
        if (((u16 *) &gSaveSlotValid)[(slot & 0xFFFF)] != 0) {
            ((u16 *) &gSlotValues)[(slot & 0xFFFF)] = 0;
            ((u16 *) &gSlotValues2)[(slot & 0xFFFF)] = 0;
            ((u16 *) &D_800E09A6)[(slot & 0xFFFF)] = 0;
            ((u16 *) &gRumbleFlags)[(slot & 0xFFFF)] = 2;
        }
        slot += 1;
    } while ((u32) (slot & 0xFFFF) < 4U);
}
